//! Taskbar integration of the main window (architecture 5):
//!  * thumbnail toolbar: prev, play/pause, next (`ITaskbarList3::ThumbBarAddButtons`), icons from
//!    `src-tauri/icons/thumb/*.ico` (generated by `scripts/gen-thumb-icons.mjs`), `WM_COMMAND` through a
//!    window subclass; the play icon follows `player.state`; setting `desktopTaskbarButtons`;
//!  * taskbar progress for downloads only (green running, yellow paused, none idle).
//!
//! Everything that touches COM runs on the main (window) thread; other threads hop there with
//! `run_on_main_thread`. The pure mappings (state -> buttons, summary -> progress, ICO selection) are unit tested.
use crate::corelink;
use crate::tray::{labels, os_lang, Labels};
use serde_json::Value;
use std::cell::RefCell;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};
use std::sync::{Arc, Mutex};
use tauri::{AppHandle, WebviewWindow};
use windows::core::w;
use windows::Win32::Foundation::{HWND, LPARAM, LRESULT, WPARAM};
use windows::Win32::System::Com::{CoCreateInstance, CLSCTX_INPROC_SERVER};
use windows::Win32::UI::Shell::{
    DefSubclassProc, ITaskbarList3, SetWindowSubclass, TaskbarList, THBF_DISABLED, THBF_ENABLED, THBF_HIDDEN, THB_FLAGS,
    THB_ICON, THB_TOOLTIP, THUMBBUTTON, THUMBBUTTONFLAGS, THUMBBUTTONMASK, TBPF_NOPROGRESS, TBPF_NORMAL, TBPF_PAUSED,
};
use windows::Win32::UI::WindowsAndMessaging::{
    CreateIconFromResourceEx, GetSystemMetrics, RegisterWindowMessageW, DestroyIcon, HICON, LR_DEFAULTCOLOR, SM_CXSMICON,
    WM_COMMAND,
};

const SUBCLASS_ID: usize = 0x4D4D_5401;
/// High word of `WM_COMMAND`'s wParam for a thumbnail button click.
const THBN_CLICKED: usize = 0x1800;

pub const ID_PREV: u32 = 0;
pub const ID_PLAY: u32 = 1;
pub const ID_NEXT: u32 = 2;

static ICO_PREV: &[u8] = include_bytes!("../../icons/thumb/prev.ico");
static ICO_PLAY: &[u8] = include_bytes!("../../icons/thumb/play.ico");
static ICO_PAUSE: &[u8] = include_bytes!("../../icons/thumb/pause.ico");
static ICO_NEXT: &[u8] = include_bytes!("../../icons/thumb/next.ico");

// ---------- pure mappings ----------

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Buttons {
    pub prev: bool,
    pub play: bool,
    pub next: bool,
    /// the play button shows the pause icon
    pub playing: bool,
}

/// `player.snapshot` / `player.state` payload -> button states. No track disables everything.
pub fn buttons_from_state(p: &Value) -> Buttons {
    let has_track = p.get("track").map(|t| !t.is_null()).unwrap_or(false);
    let b = |k: &str| p.get(k).and_then(Value::as_bool).unwrap_or(false);
    Buttons { prev: has_track && b("canPrev"), play: has_track, next: has_track && b("canNext"), playing: has_track && b("playing") }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Progress {
    None,
    Normal { done: u64, total: u64 },
    Paused { done: u64, total: u64 },
}

/// `download.summary` / `downloads.snapshot` payload -> taskbar progress. Idle (total 0) shows nothing.
pub fn progress_from_summary(p: &Value) -> Progress {
    let a = p.get("active");
    let n = |k: &str| a.and_then(|a| a.get(k)).and_then(Value::as_u64).unwrap_or(0);
    let (done, total) = (n("done"), n("total"));
    if total == 0 {
        return Progress::None;
    }
    let done = done.min(total);
    if p.get("paused").and_then(Value::as_bool).unwrap_or(false) {
        Progress::Paused { done, total }
    } else {
        Progress::Normal { done, total }
    }
}

/// Picks the ICO directory entry whose width is the smallest one `>= want`, else the widest; returns its
/// raw image bytes (a DIB or PNG, as `CreateIconFromResourceEx` expects). Pure.
pub fn pick_ico_image(ico: &[u8], want: u32) -> Option<&[u8]> {
    let rd16 = |o: usize| ico.get(o..o + 2).map(|b| u16::from_le_bytes([b[0], b[1]]) as usize);
    let rd32 = |o: usize| ico.get(o..o + 4).map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]) as usize);
    if rd16(0)? != 0 || rd16(2)? != 1 {
        return None;
    }
    let n = rd16(4)?;
    let mut best: Option<(u32, usize, usize)> = None; // (width, size, offset)
    for i in 0..n {
        let e = 6 + i * 16;
        let w = match *ico.get(e)? {
            0 => 256,
            v => v as u32,
        };
        let (size, off) = (rd32(e + 8)?, rd32(e + 12)?);
        let better = match best {
            None => true,
            Some((bw, _, _)) => (w >= want && (bw < want || w < bw)) || (bw < want && w > bw),
        };
        if better {
            best = Some((w, size, off));
        }
    }
    let (_, size, off) = best?;
    ico.get(off..off + size)
}

// ---------- COM (main thread only) ----------

struct Ui {
    tbl: ITaskbarList3,
    hwnd: HWND,
    added: bool,
    icons: [HICON; 4], // prev, play, pause, next
    btn: Buttons,
    labels: Labels,
}

thread_local! {
    static UI: RefCell<Option<Ui>> = const { RefCell::new(None) };
}

static BUTTONS_ON: AtomicBool = AtomicBool::new(true); // desktopTaskbarButtons
static TBC_MSG: AtomicU32 = AtomicU32::new(0);
static WANT: Mutex<Buttons> = Mutex::new(Buttons { prev: false, play: false, next: false, playing: false });
static WANT_PROGRESS: Mutex<Progress> = Mutex::new(Progress::None);

fn load_icon(ico: &[u8]) -> HICON {
    let px = unsafe { GetSystemMetrics(SM_CXSMICON) }.max(16) as u32;
    let Some(img) = pick_ico_image(ico, px) else { return HICON::default() };
    unsafe {
        CreateIconFromResourceEx(img, true, 0x0003_0000, px as i32, px as i32, LR_DEFAULTCOLOR).unwrap_or_default()
    }
}

fn tip(buf: &mut [u16; 260], s: &str) {
    for (i, u) in s.encode_utf16().take(259).enumerate() {
        buf[i] = u;
    }
}

fn thumb(ui: &Ui, id: u32) -> THUMBBUTTON {
    let (icon, text, enabled) = match id {
        ID_PREV => (ui.icons[0], ui.labels.prev, ui.btn.prev),
        ID_PLAY if ui.btn.playing => (ui.icons[2], ui.labels.pause, ui.btn.play),
        ID_PLAY => (ui.icons[1], ui.labels.play, ui.btn.play),
        _ => (ui.icons[3], ui.labels.next, ui.btn.next),
    };
    let flags: THUMBBUTTONFLAGS = if !BUTTONS_ON.load(Ordering::SeqCst) {
        THBF_HIDDEN
    } else if enabled {
        THBF_ENABLED
    } else {
        THBF_DISABLED
    };
    let mut b = THUMBBUTTON { dwMask: THUMBBUTTONMASK(THB_ICON.0 | THB_TOOLTIP.0 | THB_FLAGS.0), iId: id, hIcon: icon, dwFlags: flags, ..Default::default() };
    tip(&mut b.szTip, text);
    b
}

fn ensure_ui(hwnd: HWND) -> bool {
    UI.with(|u| {
        let mut u = u.borrow_mut();
        if u.is_some() {
            return true;
        }
        let tbl: windows::core::Result<ITaskbarList3> = unsafe { CoCreateInstance(&TaskbarList, None, CLSCTX_INPROC_SERVER) };
        let Ok(tbl) = tbl else { return false };
        if unsafe { tbl.HrInit() }.is_err() {
            return false;
        }
        *u = Some(Ui {
            tbl,
            hwnd,
            added: false,
            icons: [load_icon(ICO_PREV), load_icon(ICO_PLAY), load_icon(ICO_PAUSE), load_icon(ICO_NEXT)],
            btn: Buttons::default(),
            labels: labels(os_lang()),
        });
        true
    })
}

/// Brings the shell state in line with `WANT` / `WANT_PROGRESS`. Idempotent; safe to call at any time on the main thread.
fn sync(hwnd: HWND) {
    if !ensure_ui(hwnd) {
        return;
    }
    UI.with(|u| {
        let mut u = u.borrow_mut();
        let Some(ui) = u.as_mut() else { return };
        ui.btn = *WANT.lock().unwrap();
        let ids = [ID_PREV, ID_PLAY, ID_NEXT];
        let btns: Vec<THUMBBUTTON> = ids.iter().map(|&i| thumb(ui, i)).collect();
        unsafe {
            if !ui.added {
                // Fails (and is retried on the next update) while the taskbar button does not exist yet.
                if BUTTONS_ON.load(Ordering::SeqCst) && ui.tbl.ThumbBarAddButtons(ui.hwnd, &btns).is_ok() {
                    ui.added = true;
                }
            } else {
                let _ = ui.tbl.ThumbBarUpdateButtons(ui.hwnd, &btns);
            }
            match *WANT_PROGRESS.lock().unwrap() {
                Progress::None => {
                    let _ = ui.tbl.SetProgressState(ui.hwnd, TBPF_NOPROGRESS);
                }
                Progress::Normal { done, total } => {
                    let _ = ui.tbl.SetProgressState(ui.hwnd, TBPF_NORMAL);
                    let _ = ui.tbl.SetProgressValue(ui.hwnd, done, total);
                }
                Progress::Paused { done, total } => {
                    let _ = ui.tbl.SetProgressState(ui.hwnd, TBPF_PAUSED);
                    let _ = ui.tbl.SetProgressValue(ui.hwnd, done, total);
                }
            }
        }
    });
}

#[allow(dead_code)]
fn release_icons() {
    UI.with(|u| {
        if let Some(ui) = u.borrow_mut().take() {
            for i in ui.icons {
                unsafe {
                    let _ = DestroyIcon(i);
                }
            }
        }
    });
}

fn cmd(m: &'static str) {
    corelink::rt().spawn(async move {
        if let Err(e) = corelink::global().call(m, serde_json::json!({})).await {
            log::warn!("taskbar {m}: {} {}", e.code, e.msg);
        }
    });
}

unsafe extern "system" fn proc(hwnd: HWND, msg: u32, wp: WPARAM, lp: LPARAM, _id: usize, _data: usize) -> LRESULT {
    if msg != 0 && msg == TBC_MSG.load(Ordering::SeqCst) {
        // The taskbar button was (re)created, for example after an Explorer restart: add the buttons again.
        UI.with(|u| {
            if let Some(ui) = u.borrow_mut().as_mut() {
                ui.added = false;
            }
        });
        sync(hwnd);
    } else if msg == WM_COMMAND && (wp.0 >> 16) & 0xffff == THBN_CLICKED {
        match (wp.0 & 0xffff) as u32 {
            ID_PREV => cmd("player.prev"),
            ID_PLAY => cmd("player.toggle"),
            ID_NEXT => cmd("player.next"),
            _ => {}
        }
        return LRESULT(0);
    }
    DefSubclassProc(hwnd, msg, wp, lp)
}

fn on_main(app: &AppHandle, hwnd: HWND) {
    let addr = hwnd.0 as usize;
    let _ = app.run_on_main_thread(move || sync(HWND(addr as *mut _)));
}

/// Applies one `settings` payload: `desktopTaskbarButtons`.
pub fn apply_settings(payload: &Value) -> bool {
    let m = payload.get("values").or_else(|| payload.get("changed")).unwrap_or(payload);
    match m.get("desktopTaskbarButtons").and_then(Value::as_bool) {
        Some(b) => {
            BUTTONS_ON.store(b, Ordering::SeqCst);
            true
        }
        None => false,
    }
}

/// Setup block of M2-4. Must run before the main window is first shown so `TaskbarButtonCreated` is not missed.
pub fn install(app: &AppHandle, win: &WebviewWindow) {
    let Ok(h) = win.hwnd() else { return };
    let hwnd = HWND(h.0);
    if let Some(b) = crate::window_state::store().and_then(|s| s.get("desktopTaskbarButtons")).and_then(|v| v.as_bool()) {
        BUTTONS_ON.store(b, Ordering::SeqCst);
    }
    unsafe {
        TBC_MSG.store(RegisterWindowMessageW(w!("TaskbarButtonCreated")), Ordering::SeqCst);
        let _ = SetWindowSubclass(hwnd, Some(proc), SUBCLASS_ID, 0);
    }
    let link = corelink::global();
    let (a1, addr) = (app.clone(), hwnd.0 as usize);
    link.subscribe(
        "player",
        Arc::new(move |ev, p| {
            if ev == "player.snapshot" || ev == "player.state" {
                *WANT.lock().unwrap() = buttons_from_state(p);
                on_main(&a1, HWND(addr as *mut _));
            }
        }),
    );
    let a2 = app.clone();
    link.subscribe(
        "downloads",
        Arc::new(move |ev, p| {
            if ev == "download.summary" || ev == "downloads.snapshot" {
                *WANT_PROGRESS.lock().unwrap() = progress_from_summary(p);
                on_main(&a2, HWND(addr as *mut _));
            }
        }),
    );
    let a3 = app.clone();
    link.subscribe(
        "settings",
        Arc::new(move |_ev, p| {
            if apply_settings(p) {
                on_main(&a3, HWND(addr as *mut _));
            }
        }),
    );
    on_main(app, hwnd);
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn buttons_follow_player_state() {
        let p = json!({"track": {"id": "a"}, "playing": true, "canPrev": false, "canNext": true});
        assert_eq!(buttons_from_state(&p), Buttons { prev: false, play: true, next: true, playing: true });
        let paused = json!({"track": {"id": "a"}, "playing": false, "canPrev": true, "canNext": true});
        assert_eq!(buttons_from_state(&paused), Buttons { prev: true, play: true, next: true, playing: false });
    }

    #[test]
    fn no_track_disables_everything() {
        let p = json!({"track": null, "playing": true, "canPrev": true, "canNext": true});
        assert_eq!(buttons_from_state(&p), Buttons::default());
        assert_eq!(buttons_from_state(&json!({})), Buttons::default());
    }

    #[test]
    fn progress_mapping() {
        let run = json!({"active": {"done": 3, "total": 10}, "paused": false});
        assert_eq!(progress_from_summary(&run), Progress::Normal { done: 3, total: 10 });
        let paused = json!({"active": {"done": 3, "total": 10}, "paused": true});
        assert_eq!(progress_from_summary(&paused), Progress::Paused { done: 3, total: 10 });
        let idle = json!({"active": {"done": 0, "total": 0}, "paused": false});
        assert_eq!(progress_from_summary(&idle), Progress::None);
        assert_eq!(progress_from_summary(&json!({})), Progress::None);
        let over = json!({"active": {"done": 12, "total": 10}});
        assert_eq!(progress_from_summary(&over), Progress::Normal { done: 10, total: 10 });
    }

    fn ico(widths: &[u8]) -> Vec<u8> {
        let mut v = vec![0, 0, 1, 0, widths.len() as u8, 0];
        let mut off = 6 + 16 * widths.len();
        for w in widths {
            v.extend([*w, *w, 0, 0, 1, 0, 32, 0]);
            v.extend(4u32.to_le_bytes());
            v.extend((off as u32).to_le_bytes());
            off += 4;
        }
        for w in widths {
            v.extend([*w; 4]);
        }
        v
    }

    #[test]
    fn ico_picks_the_smallest_sufficient_size() {
        let f = ico(&[16, 20, 24, 32]);
        assert_eq!(pick_ico_image(&f, 16), Some(&[16u8; 4][..]));
        assert_eq!(pick_ico_image(&f, 20), Some(&[20u8; 4][..]));
        assert_eq!(pick_ico_image(&f, 22), Some(&[24u8; 4][..]));
        assert_eq!(pick_ico_image(&f, 48), Some(&[32u8; 4][..]));
        assert_eq!(pick_ico_image(&[1, 2, 3], 16), None);
    }

    #[test]
    fn bundled_icons_are_valid() {
        for i in [ICO_PREV, ICO_PLAY, ICO_PAUSE, ICO_NEXT] {
            for px in [16, 20, 24, 32] {
                assert!(pick_ico_image(i, px).is_some());
            }
        }
    }

    #[test]
    fn settings_toggle() {
        assert!(apply_settings(&json!({"changed": {"desktopTaskbarButtons": false}})));
        assert!(!BUTTONS_ON.load(Ordering::SeqCst));
        assert!(!apply_settings(&json!({"changed": {"x": 1}})));
        BUTTONS_ON.store(true, Ordering::SeqCst);
    }
}
